		library IEEE;		use IEEE_std_logic_1164.all;entity Prob_5_41_vhdl is	port  (y_out: out bit; x_in, clock, reset_b: in bit);end Prob_5_41_vhdl;architecture Behavioral of Prob_5_41_vhdl is	constant s0: Std_Logic_vector (2 downto 0) := "000";  	constant s1: Std_Logic_vector (2 downto 0) := "001";	constant s2: Std_Logic_vector (2 downto 0) := "010";	constant s3: Std_Logic_vector (2 downto 0) := "011";	constant s4: Std_Logic_vector (2 downto 0) := "100"; 	signal state, next_state: Std_Logic_vector (2 downto 0);begin	process (clock, reset_b) begin		if reset_b = '0' then state <= s0;     		elsif clock'event and clock = '1' then state <= next_state; end if;	end process;  	process (state, x_in) begin    		y_out <= '0';    		next_state <= s0;    		case (state) is      		when s0 =>	if x_in = '1' then next_state <= s4; y_out <= '1'; 								else next_state <= s3; y_out <= '0'; end if;      				when s1 =>	if x_in = '1' then next_state <= s4; y_out <= '1'; 								else next_state <= s1; y_out <= '0'; end if;      		when s2 =>	if x_in = '1' then next_state <= s0; y_out <= '1'; 								else next_state <= s2; y_out <= '0'; end if;      		when s3 =>	if x_in = '1' then next_state <= s2; y_out <= '1'; 								else next_state <= s1; y_out <= '0'; end if;       		when s4 =>	if x_in = '1' then next_state <= s3; y_out <= '0'; 								else next_state <= s2; y_out <= '0'; end if;      		when others =>	next_state <= "xxx";    		end case;  	end process;end  Behavioral;